prompt --application/deployment/install/install_install
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(282258105068138389)
,p_install_id=>wwv_flow_imp.id(282257277200155981)
,p_name=>'install'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  CREATE TABLE "DEMO_QUOTE_HDR" ',
'   (	"QUOTE_HDR_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"INTERNAL_QUOTE_NO" VARCHAR2(30), ',
'	"EXTERNAL_QUOTE_ID" VARCHAR2(50), ',
'	"TRACE_ID" VARCHAR2(50), ',
'	"CUSTOMER_DOC" VARCHAR2(30) NOT NULL ENABLE, ',
'	"CUSTOMER_ID" VARCHAR2(30), ',
'	"PRODUCT_ID" VARCHAR2(30) NOT NULL ENABLE, ',
'	"QTY" NUMBER NOT NULL ENABLE, ',
'	"ZIP_CODE" VARCHAR2(20), ',
'	"NORMALIZED_ZIP" VARCHAR2(20), ',
'	"SALES_CHANNEL" VARCHAR2(30), ',
'	"TOTAL_AMOUNT" NUMBER(15,2), ',
'	"CURRENCY_CODE" VARCHAR2(10), ',
'	"STATUS_CODE" VARCHAR2(30), ',
'	"RESPONSE_JSON" CLOB, ',
'	"CREATED_ON" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, ',
'	"CREATED_BY" VARCHAR2(255) DEFAULT coalesce(sys_context(''APEX$SESSION'',''APP_USER''), user) NOT NULL ENABLE, ',
'	 CONSTRAINT "DEMO_QUOTE_HDR_CK1" CHECK (qty > 0) ENABLE, ',
'	 CONSTRAINT "DEMO_QUOTE_HDR_PK" PRIMARY KEY ("QUOTE_HDR_ID")',
'  USING INDEX  ENABLE, ',
'	 CONSTRAINT "DEMO_QUOTE_HDR_UK1" UNIQUE ("INTERNAL_QUOTE_NO")',
'  USING INDEX  ENABLE',
'   ) ;',
'',
'  CREATE TABLE "DEMO_QUOTE_LINE" ',
'   (	"QUOTE_LINE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"QUOTE_HDR_ID" NUMBER NOT NULL ENABLE, ',
'	"LINE_NO" NUMBER NOT NULL ENABLE, ',
'	"ITEM_CODE" VARCHAR2(30), ',
'	"DESCRIPTION" VARCHAR2(200), ',
'	"QTY" NUMBER(15,2), ',
'	"UNIT_PRICE" NUMBER(15,2), ',
'	"LINE_TOTAL" NUMBER(15,2), ',
'	"CREATED_ON" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, ',
'	 CONSTRAINT "DEMO_QUOTE_LINE_PK" PRIMARY KEY ("QUOTE_LINE_ID")',
'  USING INDEX  ENABLE',
'   ) ;',
'',
'  ALTER TABLE "DEMO_QUOTE_LINE" ADD CONSTRAINT "DEMO_QUOTE_LINE_FK1" FOREIGN KEY ("QUOTE_HDR_ID")',
'	  REFERENCES "DEMO_QUOTE_HDR" ("QUOTE_HDR_ID") ON DELETE CASCADE ENABLE;',
'',
'  CREATE INDEX "DEMO_QUOTE_LINE_I1" ON "DEMO_QUOTE_LINE" ("QUOTE_HDR_ID") ',
'  ;',
'create or replace package pkg_demo_quote authid definer as',
'',
'  procedure validate_request (',
'      p_customer_doc      in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_zip_code          in  varchar2,',
'      p_customer_id       out varchar2,',
'      p_normalized_zip    out varchar2,',
'      p_trace_id          out varchar2,',
'      p_request_ok        out varchar2,',
'      p_message           out varchar2',
'  );',
'',
'  procedure invoke_pricing (',
'      p_customer_id       in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_normalized_zip    in  varchar2,',
'      p_trace_id          in  varchar2,',
'      p_quote_id          out varchar2,',
'      p_total_amount      out number,',
'      p_currency          out varchar2,',
'      p_status_code       out varchar2,',
'      p_response_json     out clob',
'  );',
'',
'  procedure response_to_collection (',
'      p_response_json     in  clob,',
'      p_collection_name   in  varchar2 default ''QUOTE_LINES''',
'  );',
'',
'  procedure save_quote (',
'      p_customer_doc      in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_zip_code          in  varchar2,',
'      p_sales_channel     in  varchar2,',
'      p_customer_id       in  varchar2,',
'      p_normalized_zip    in  varchar2,',
'      p_trace_id          in  varchar2,',
'      p_quote_id          in  varchar2,',
'      p_total_amount      in  number,',
'      p_currency          in  varchar2,',
'      p_status_code       in  varchar2,',
'      p_response_json     in  clob,',
'      p_collection_name   in  varchar2 default ''QUOTE_LINES'',',
'      p_internal_quote_no out varchar2',
'  );',
'',
'end pkg_demo_quote;',
'/',
'',
'',
'create or replace package body pkg_demo_quote as',
'',
'  ------------------------------------------------------------------------------',
'  -- Helpers',
'  ------------------------------------------------------------------------------',
'  function normalize_digits (',
'      p_value in varchar2',
'  ) return varchar2',
'  is',
'  begin',
'    return regexp_replace(nvl(p_value, ''''), ''[^0-9]'', '''');',
'  end normalize_digits;',
'',
'  function get_base_price (',
'      p_product_id in varchar2',
'  ) return number',
'  is',
'  begin',
'    return case upper(trim(p_product_id))',
'             when ''PRD-100'' then 1000',
'             when ''PRD-200'' then 1750',
'             when ''PRD-300'' then 2300',
'             else 890',
'           end;',
'  end get_base_price;',
'',
'  function get_freight (',
'      p_normalized_zip in varchar2',
'  ) return number',
'  is',
'    l_zip_prefix number;',
'  begin',
'    if p_normalized_zip is null then',
'      return 300;',
'    end if;',
'',
'    l_zip_prefix := to_number(substr(p_normalized_zip, 1, 2));',
'',
'    return case',
'             when l_zip_prefix between 1 and 29 then 220',
'             when l_zip_prefix between 30 and 59 then 250',
'             when l_zip_prefix between 60 and 99 then 320',
'             else 300',
'           end;',
'  exception',
'    when others then',
'      return 300;',
'  end get_freight;',
'',
'  ------------------------------------------------------------------------------',
'  -- 1) VALIDATE_REQUEST',
'  ------------------------------------------------------------------------------',
'  procedure validate_request (',
'      p_customer_doc      in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_zip_code          in  varchar2,',
'      p_customer_id       out varchar2,',
'      p_normalized_zip    out varchar2,',
'      p_trace_id          out varchar2,',
'      p_request_ok        out varchar2,',
'      p_message           out varchar2',
'  )',
'  is',
'    l_customer_doc varchar2(30);',
'    l_zip_code     varchar2(20);',
'  begin',
'    l_customer_doc := normalize_digits(p_customer_doc);',
'    l_zip_code     := normalize_digits(p_zip_code);',
'',
'    if p_product_id is null then',
'      p_request_ok      := ''N'';',
'      p_message         := ''Product is required.'';',
'      p_customer_id     := null;',
'      p_normalized_zip  := null;',
'      p_trace_id        := null;',
'      return;',
'    end if;',
'',
'    if nvl(p_qty, 0) <= 0 then',
'      p_request_ok      := ''N'';',
'      p_message         := ''Quantity must be greater than zero.'';',
'      p_customer_id     := null;',
'      p_normalized_zip  := null;',
'      p_trace_id        := null;',
'      return;',
'    end if;',
'',
'    if length(l_customer_doc) not in (11, 14) then',
'      p_request_ok      := ''N'';',
'      p_message         := ''Customer document must contain 11 or 14 digits.'';',
'      p_customer_id     := null;',
'      p_normalized_zip  := null;',
'      p_trace_id        := null;',
'      return;',
'    end if;',
'',
'    if length(l_zip_code) <> 8 then',
'      p_request_ok      := ''N'';',
'      p_message         := ''ZIP code must contain 8 digits.'';',
'      p_customer_id     := null;',
'      p_normalized_zip  := null;',
'      p_trace_id        := null;',
'      return;',
'    end if;',
'',
'    p_customer_id     := ''CUST-'' || lpad(substr(l_customer_doc, greatest(1, length(l_customer_doc) - 7)), 8, ''0'');',
'    p_normalized_zip  := l_zip_code;',
'    p_trace_id        := ''TRC-'' || to_char(systimestamp, ''YYYYMMDDHH24MISSFF3'');',
'    p_request_ok      := ''Y'';',
'    p_message         := ''Request validated successfully.'';',
'  end validate_request;',
'',
'  ------------------------------------------------------------------------------',
'  -- 2) INVOKE_PRICING',
'  ------------------------------------------------------------------------------',
'  procedure invoke_pricing (',
'      p_customer_id       in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_normalized_zip    in  varchar2,',
'      p_trace_id          in  varchar2,',
'      p_quote_id          out varchar2,',
'      p_total_amount      out number,',
'      p_currency          out varchar2,',
'      p_status_code       out varchar2,',
'      p_response_json     out clob',
'  )',
'  is',
'    l_base_price    number;',
'    l_freight       number;',
'    l_product_total number;',
'  begin',
'    if p_customer_id is null then',
'      raise_application_error(-20001, ''Customer ID is required for pricing.'');',
'    end if;',
'',
'    if nvl(p_qty, 0) <= 0 then',
'      raise_application_error(-20002, ''Quantity must be greater than zero for pricing.'');',
'    end if;',
'',
'    l_base_price    := get_base_price(p_product_id);',
'    l_freight       := get_freight(p_normalized_zip);',
'    l_product_total := l_base_price * p_qty;',
'',
'    p_quote_id      := ''Q-'' || to_char(systimestamp, ''YYYYMMDDHH24MISSFF3'');',
'    p_total_amount  := l_product_total + l_freight;',
'    p_currency      := ''USD'';',
'    p_status_code   := ''SUCCESS'';',
'',
'    select json_object(',
'             ''quote_id''     value p_quote_id,',
'             ''currency''     value p_currency,',
'             ''total_amount'' value p_total_amount,',
'             ''status_code''  value p_status_code,',
'             ''trace_id''     value p_trace_id,',
'             ''lines''        value json_array(',
'                               json_object(',
'                                 ''line_no''     value 1,',
'                                 ''item_code''   value upper(trim(p_product_id)),',
'                                 ''description'' value ''Base Product'',',
'                                 ''qty''         value p_qty,',
'                                 ''unit_price''  value l_base_price,',
'                                 ''line_total''  value l_product_total',
'                               ),',
'                               json_object(',
'                                 ''line_no''     value 2,',
'                                 ''item_code''   value ''FRT-001'',',
'                                 ''description'' value ''Freight'',',
'                                 ''qty''         value 1,',
'                                 ''unit_price''  value l_freight,',
'                                 ''line_total''  value l_freight',
'                               )',
'                             )',
'             returning clob',
'           )',
'      into p_response_json',
'      from dual;',
'  end invoke_pricing;',
'',
'  ------------------------------------------------------------------------------',
'  -- 3) RESPONSE_TO_COLLECTION',
'  ------------------------------------------------------------------------------',
'  procedure response_to_collection (',
'      p_response_json     in  clob,',
'      p_collection_name   in  varchar2 default ''QUOTE_LINES''',
'  )',
'  is',
'  begin',
'    if p_response_json is null then',
'      raise_application_error(-20003, ''Response JSON is required to populate the collection.'');',
'    end if;',
'',
'    apex_collection.create_or_truncate_collection(',
'      p_collection_name => upper(p_collection_name)',
'    );',
'',
'    for r in (',
'      select jt.line_no,',
'             jt.item_code,',
'             jt.description,',
'             jt.qty,',
'             jt.unit_price,',
'             jt.line_total',
'        from json_table(',
'               p_response_json,',
'               ''$.lines[*]''',
'               columns (',
'                 line_no     number         path ''$.line_no'',',
'                 item_code   varchar2(30)   path ''$.item_code'',',
'                 description varchar2(200)  path ''$.description'',',
'                 qty         number         path ''$.qty'',',
'                 unit_price  number         path ''$.unit_price'',',
'                 line_total  number         path ''$.line_total''',
'               )',
'             ) jt',
'    ) loop',
'      apex_collection.add_member(',
'        p_collection_name => upper(p_collection_name),',
'        p_c001            => to_char(r.line_no),',
'        p_c002            => r.item_code,',
'        p_c003            => r.description,',
'        p_n001            => r.qty,',
'        p_n002            => r.unit_price,',
'        p_n003            => r.line_total',
'      );',
'    end loop;',
'  end response_to_collection;',
'',
'  ------------------------------------------------------------------------------',
'  -- 4) SAVE_QUOTE',
'  ------------------------------------------------------------------------------',
'  procedure save_quote (',
'      p_customer_doc      in  varchar2,',
'      p_product_id        in  varchar2,',
'      p_qty               in  number,',
'      p_zip_code          in  varchar2,',
'      p_sales_channel     in  varchar2,',
'      p_customer_id       in  varchar2,',
'      p_normalized_zip    in  varchar2,',
'      p_trace_id          in  varchar2,',
'      p_quote_id          in  varchar2,',
'      p_total_amount      in  number,',
'      p_currency          in  varchar2,',
'      p_status_code       in  varchar2,',
'      p_response_json     in  clob,',
'      p_collection_name   in  varchar2 default ''QUOTE_LINES'',',
'      p_internal_quote_no out varchar2',
'  )',
'  is',
'    l_quote_hdr_id   number;',
'    l_line_count     number;',
'    l_customer_doc   varchar2(30);',
'    l_zip_code       varchar2(20);',
'    l_product_id     varchar2(30);',
'    l_sales_channel  varchar2(30);',
'  begin',
'    l_customer_doc  := normalize_digits(p_customer_doc);',
'    l_zip_code      := normalize_digits(p_zip_code);',
'    l_product_id    := upper(trim(p_product_id));',
'    l_sales_channel := upper(trim(p_sales_channel));',
'',
'    select count(*)',
'      into l_line_count',
'      from apex_collections',
'     where collection_name = upper(p_collection_name);',
'',
'    if l_line_count = 0 then',
'      raise_application_error(-20004, ''Collection '' || upper(p_collection_name) || '' is empty.'');',
'    end if;',
'',
'    insert into demo_quote_hdr (',
'        internal_quote_no,',
'        external_quote_id,',
'        trace_id,',
'        customer_doc,',
'        customer_id,',
'        product_id,',
'        qty,',
'        zip_code,',
'        normalized_zip,',
'        sales_channel,',
'        total_amount,',
'        currency_code,',
'        status_code,',
'        response_json',
'    ) values (',
'        null,',
'        p_quote_id,',
'        p_trace_id,',
'        l_customer_doc,',
'        p_customer_id,',
'        l_product_id,',
'        p_qty,',
'        l_zip_code,',
'        p_normalized_zip,',
'        l_sales_channel,',
'        p_total_amount,',
'        p_currency,',
'        p_status_code,',
'        p_response_json',
'    )',
'    returning quote_hdr_id into l_quote_hdr_id;',
'',
'    p_internal_quote_no := ''INT-'' || lpad(l_quote_hdr_id, 6, ''0'');',
'',
'    update demo_quote_hdr',
'       set internal_quote_no = p_internal_quote_no',
'     where quote_hdr_id = l_quote_hdr_id;',
'',
'    insert into demo_quote_line (',
'        quote_hdr_id,',
'        line_no,',
'        item_code,',
'        description,',
'        qty,',
'        unit_price,',
'        line_total',
'    )',
'    select l_quote_hdr_id,',
'           to_number(c001),',
'           c002,',
'           c003,',
'           n001,',
'           n002,',
'           n003',
'      from apex_collections',
'     where collection_name = upper(p_collection_name);',
'',
'  end save_quote;',
'',
'end pkg_demo_quote;',
'/',
'',
' '))
);
